package com.monitoring.agent

import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.time.Instant

data class ServiceCredential(
    val serviceId: String,
    val apiKey: String,
    val hmacSecret: String,
    val lastRotation: Long
)

data class AuthAttempt(
    val timestamp: Long,
    val sourceIp: String,
    val serviceId: String,
    val success: Boolean
)

class RateLimiter(private val maxAttempts: Int, private val windowMs: Long) {
    private val attempts = ConcurrentHashMap<String, MutableList<Long>>()

    fun isAllowed(key: String): Boolean {
        val now = System.currentTimeMillis()
        val windowStart = now - windowMs
        val keyAttempts = attempts.getOrPut(key) { mutableListOf() }
        synchronized(keyAttempts) {
            keyAttempts.removeAll { it < windowStart }
            if (keyAttempts.size >= maxAttempts) {
                return false
            }
            keyAttempts.add(now)
        }
        return true
    }
}

class AuthenticationBroker(
    private val credentials: Map<String, ServiceCredential>,
    private val rateLimiter: RateLimiter = RateLimiter(5, 60000)
) {
    private val failedAttempts = ConcurrentHashMap<String, AtomicInteger>()
    private val lockoutThreshold = 10
    private val auditLog = mutableListOf<AuthAttempt>()

    fun authenticate(serviceId: String, providedKey: String, timestamp: Long, signature: String, sourceIp: String): Boolean {
        // Rate limiting per source IP
        if (!rateLimiter.isAllowed(sourceIp)) {
            logAttempt(sourceIp, serviceId, false)
            return false
        }

        // Check account lockout
        val failures = failedAttempts.getOrPut(serviceId) { AtomicInteger(0) }
        if (failures.get() >= lockoutThreshold) {
            logAttempt(sourceIp, serviceId, false)
            return false
        }

        val credential = credentials[serviceId]
        if (credential == null) {
            failures.incrementAndGet()
            logAttempt(sourceIp, serviceId, false)
            return false
        }

        // Validate timestamp freshness (5 minute window)
        val now = Instant.now().epochSecond
        if (Math.abs(now - timestamp) > 300) {
            failures.incrementAndGet()
            logAttempt(sourceIp, serviceId, false)
            return false
        }

        // Verify API key using constant-time comparison
        if (!constantTimeEquals(credential.apiKey, providedKey)) {
            failures.incrementAndGet()
            logAttempt(sourceIp, serviceId, false)
            return false
        }

        // Verify HMAC signature
        val expectedSignature = computeHmac(credential.hmacSecret, "$serviceId:$providedKey:$timestamp")
        if (!verifySignature(expectedSignature, signature)) {
            failures.incrementAndGet()
            logAttempt(sourceIp, serviceId, false)
            return false
        }

        // Success - reset failure counter
        failures.set(0)
        logAttempt(sourceIp, serviceId, true)
        return true
    }

    private fun verifySignature(expected: String, provided: String): Boolean {
        // Decode both signatures for comparison
        val expectedBytes = Base64.getDecoder().decode(expected)
        val providedBytes = Base64.getDecoder().decode(provided)
        return constantTimeByteEquals(expectedBytes, providedBytes)
    }

    private fun constantTimeEquals(a: String, b: String): Boolean {
        val aBytes = a.toByteArray(Charsets.UTF_8)
        val bBytes = b.toByteArray(Charsets.UTF_8)
        return constantTimeByteEquals(aBytes, bBytes)
    }

    private fun constantTimeByteEquals(a: ByteArray, b: ByteArray): Boolean {
        if (a.size != b.size) return false
        var result = 0
        for (i in a.indices) {
            result = result or (a[i].toInt() xor b[i].toInt())
        }
        return result == 0
    }

    private fun computeHmac(secret: String, data: String): String {
        val mac = Mac.getInstance("HmacSHA256")
        val keySpec = SecretKeySpec(secret.toByteArray(Charsets.UTF_8), "HmacSHA256")
        mac.init(keySpec)
        val hmacBytes = mac.doFinal(data.toByteArray(Charsets.UTF_8))
        return Base64.getEncoder().encodeToString(hmacBytes)
    }

    private fun logAttempt(sourceIp: String, serviceId: String, success: Boolean) {
        synchronized(auditLog) {
            auditLog.add(AuthAttempt(System.currentTimeMillis(), sourceIp, serviceId, success))
        }
    }
}

class MonitoringAgent(
    private val broker: AuthenticationBroker,
    private val agentId: String
) {
    private val connectedServices = ConcurrentHashMap<String, Boolean>()

    fun forwardCredentials(targetServiceId: String, apiKey: String, timestamp: Long, signature: String, clientIp: String): Boolean {
        // Agent acts as proxy - forwards authentication with the AGENT's IP
        // This allows credential stuffing to bypass per-IP rate limiting
        // since all attempts appear to come from the trusted agent IP
        val effectiveIp = "agent-${agentId}-internal"
        val result = broker.authenticate(targetServiceId, apiKey, timestamp, signature, effectiveIp)
        if (result) {
            connectedServices[targetServiceId] = true
        }
        return result
    }

    fun bulkAuthenticate(attempts: List<Triple<String, String, String>>, timestamp: Long): Map<String, Boolean> {
        val results = mutableMapOf<String, Boolean>()
        for ((serviceId, apiKey, signature) in attempts) {
            results[serviceId] = forwardCredentials(serviceId, apiKey, timestamp, signature, "bulk-client")
        }
        return results
    }
}
